<div class="card p-4"><div class="row">
<div class="col-md-6 mb-3"><label class="form-label">Tipo de movimiento *</label><select class="form-select" name="tipo" id="tipo" required><option value="ingreso" @selected(old('tipo',$transaccion->tipo)==='ingreso')>Ingreso</option><option value="gasto" @selected(old('tipo',$transaccion->tipo)==='gasto')>Gasto</option></select></div>
<div class="col-md-6 mb-3"><label class="form-label">Cuenta *</label><select class="form-select" name="cuenta_id" required><option value="">Selecciona una cuenta</option>@foreach($cuentas as $c)<option value="{{ $c->id }}" @selected((string)old('cuenta_id',$transaccion->cuenta_id)===(string)$c->id)>{{ $c->nombre }} · ${{ number_format((float)$c->saldo,2,',','.') }}</option>@endforeach</select></div>
<div class="col-md-6 mb-3"><label class="form-label">Categoría *</label><select class="form-select" name="categoria_id" id="categoria_id" required><option value="">Selecciona una categoría</option>@foreach($categorias as $cat)<option value="{{ $cat->id }}" data-tipo="{{ $cat->tipo }}" @selected((string)old('categoria_id',$transaccion->categoria_id)===(string)$cat->id)>{{ $cat->nombre }} ({{ $cat->tipo }})</option>@endforeach</select><div class="form-text">La categoría debe corresponder al tipo de movimiento.</div></div>
<div class="col-md-6 mb-3"><label class="form-label">Monto (COP) *</label><input class="form-control" type="number" name="monto" min="0.01" step="0.01" value="{{ old('monto',$transaccion->monto) }}" required placeholder="Ej. 50000"></div>
<div class="col-md-6 mb-3"><label class="form-label">Fecha *</label><input class="form-control" type="date" name="fecha" value="{{ old('fecha',$transaccion->fecha?->format('Y-m-d') ?? now()->format('Y-m-d')) }}" required></div>
<div class="col-md-6 mb-3"><label class="form-label">Descripción</label><input class="form-control" name="descripcion" maxlength="255" value="{{ old('descripcion',$transaccion->descripcion) }}" placeholder="Detalle del movimiento"></div></div>
<div class="alert alert-warning small"><i class="bi bi-shield-check me-1"></i>Los gastos no pueden superar el saldo disponible. Al editar o eliminar, el sistema recalcula el saldo automáticamente.</div>
<button class="btn btn-success"><i class="bi bi-check-lg me-1"></i>Guardar movimiento</button> <a href="{{ route('transacciones.index') }}" class="btn btn-light">Cancelar</a></div>
@push('scripts')<script>const tipo=document.getElementById('tipo'), categoria=document.getElementById('categoria_id');function filtrarCategorias(){let actual=categoria.value;[...categoria.options].forEach((o,i)=>{if(i===0)return;o.hidden=o.dataset.tipo!==tipo.value;if(o.hidden&&o.value===actual)categoria.value='';});}tipo.addEventListener('change',filtrarCategorias);filtrarCategorias();</script>@endpush
